WITH scored AS (SELECT id, customer_id, device, browser, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at DESC, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at, id) AS event_seq_2, LAST_VALUE(country) IGNORE NULLS OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at, id) AS seq_no, ROW_NUMBER() OVER w_ordered AS event_seq_3 FROM sessions WHERE browser = 'Chrome' WINDOW w_ordered AS (PARTITION BY MONTH(started_at) ORDER BY started_at, id)) SELECT CASE WHEN seq_no >= 8 THEN 'HIGH' ELSE 'LOW' END AS seq_no_tier, device, COUNT(DISTINCT browser) AS distinct_browsers, PERCENTILE_APPROX(event_seq, ARRAY(0.25, 0.5, 0.75)) AS event_seq_quartiles, ROUND(SUM(event_seq) / NULLIF(COUNT(CASE WHEN device = 'desktop' THEN 1 END), 0), 2) AS event_seq_per_desktop FROM scored GROUP BY CASE WHEN seq_no >= 8 THEN 'HIGH' ELSE 'LOW' END, device;
